+'use client'
+
+import { useEffect, useState } from 'react'
+
+type ApiResult = { data: unknown } | { error: string }
+
+type DashboardResults = {
+  analytics: ApiResult | null
+  notifications: ApiResult | null
+  settings: ApiResult | null
+}
+
+const initialResults: DashboardResults = {
+  analytics: null,
+  notifications: null,
+  settings: null,
+}
+
+async function fetchJson(url: string, signal: AbortSignal): Promise<ApiResult> {
+  try {
+    const response = await fetch(url, { signal })
+
+    if (!response.ok) {
+      return { error: `Request failed (${response.status})` }
+    }
+
+    return { data: await response.json() }
+  } catch {
+    return { error: 'Unable to load this data.' }
+  }
+}
+
+function DataPanel({
+  title,
+  result,
+}: {
+  title: string
+  result: ApiResult | null
+}) {
+  return (
+    <section aria-labelledby={`${title.toLowerCase()}-heading`}>
+      <h3 id={`${title.toLowerCase()}-heading`}>{title}</h3>
+      {result === null ? (
+        <p role="status">Loading {title.toLowerCase()}…</p>
+      ) : 'error' in result ? (
+        <p role="alert">{result.error}</p>
+      ) : (
+        <pre>{JSON.stringify(result.data, null, 2)}</pre>
+      )}
+    </section>
+  )
+}
+
+export default function Dashboard() {
+  const [results, setResults] = useState(initialResults)
+
+  useEffect(() => {
+    const controller = new AbortController()
+    let active = true
+
+    Promise.all([
+      fetchJson('/api/analytics', controller.signal),
+      fetchJson('/api/notifications', controller.signal),
+      fetchJson('/api/settings', controller.signal),
+    ]).then(([analytics, notifications, settings]) => {
+      if (active) {
+        setResults({ analytics, notifications, settings })
+      }
+    })
+
+    return () => {
+      active = false
+      controller.abort()
+    }
+  }, [])

   return (
     <div>
-      <h2>Dashboard Content</h2>
-      <p>Dashboard data will go here</p>
+      <h2>Dashboard</h2>
+      <DataPanel title="Analytics" result={results.analytics} />
+      <DataPanel title="Notifications" result={results.notifications} />
+      <DataPanel title="Settings" result={results.settings} />
     </div>
   )
 }
